                base = costs[u]
                if base is None:
                    continue
                row = matrix[u]
                for v in range(n):
                    weight = row[v]
                    if weight is not None:
                        candidate = base + weight
                        old = updated[v]
                        if old is None or candidate < old:
                            updated[v] = candidate
            costs = updated

        k //= 2
        if not k:
            break

        squared = [[None] * n for _ in range(n)]
        for u in range(n):
            result_row = squared[u]
            for mid in range(n):
