            dist = next_dist

        k //= 2
        if k:
            next_power = [[None] * n for _ in range(n)]
            for i in range(n):
                result_row = next_power[i]
                for middle in range(n):
                    left = power[i][middle]
                    if left is not None:
                        right_row = power[middle]
                        for j in range(n):
                            if right_row[j] is not None:
                                cost = left + right_row[j]
                                if result_row[j] is None or cost < result_row[j]:
                                    result_row[j] = cost
            power = next_power

    return dist[target]

def solve(data):
    source = data["source"]
    target = data["target"]
    k = data["k"]
    costs = {source: 0}
    if k == 0:
        return costs.get(target)

    steps = {}
    nonnegative = True
    for u, v, weight in data["edges"]:
        row = steps.setdefault(u, {})
        if v not in row or weight < row[v]:
            row[v] = weight
        if weight < 0:
            nonnegative = False

    def advance(current, paths):
        result = current.copy()
        for u, cost in current.items():
            for v, weight in paths.get(u, {}).items():
                candidate = cost + weight
                if v not in result or candidate < result[v]:
                    result[v] = candidate
        return result

    if nonnegative:
        k = min(k, data["n"] - 1, len(steps))

    if k <= max(16, len(steps)):
        for _ in range(k):
            updated = advance(costs, steps)
            if updated == costs:
                break
            costs = updated
    else:
        while k:
            if k % 2:
                costs = advance(costs, steps)
            k //= 2
            if k:
                doubled = {u: advance(row, steps) for u, row in steps.items()}
                if doubled == steps:
                    costs = advance(costs, steps)
                    break
                steps = doubled

    return costs.get(target)

