def solve(data):
    n = data["n"]
    edges = data["edges"]
    source = data["source"]
    target = data["target"]
    k = data["k"]

    if k == 0:
        return 0 if source == target else None

    forward = [[] for _ in range(n)]
    reverse = [[] for _ in range(n)]
    for u, v, weight in edges:
        forward[u].append(v)
        reverse[v].append(u)

    def reachable(start, graph):
        seen = [False] * n
        seen[start] = True
        stack = [start]
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        return seen

    from_source = reachable(source, forward)
    if not from_source[target]:
        return None
    to_target = reachable(target, reverse)

    index = {}
    for u in range(n):
        if from_source[u] and to_target[u]:
            index[u] = len(index)

    size = len(index)
    start = index[source]
    end = index[target]
    outgoing = [[] for _ in range(size)]
    for u, v, weight in edges:
        if u in index and v in index:
            outgoing[index[u]].append((index[v], weight))

    distances = {start: 0}
    frontier = {start: 0}
    steps = 0
    scanned = 0

    while steps < k and steps < size and scanned < 2000000:
        improved = {}
        for u, cost in frontier.items():
            scanned += len(outgoing[u])
            for v, weight in outgoing[u]:
                candidate = cost + weight
                previous = distances.get(v)
                if previous is None or candidate < previous:
                    previous = improved.get(v)
                    if previous is None or candidate < previous:
                        improved[v] = candidate

        if not improved:
            return distances.get(end)

        distances.update(improved)
        frontier = improved
        steps += 1

    remaining = k - steps
    if remaining == 0:
        return distances.get(end)

    matrix = [{i: 0} for i in range(size)]
    for u in range(size):
        row = matrix[u]
        for v, weight in outgoing[u]:
            previous = row.get(v)
            if previous is None or weight < previous:
                row[v] = weight

    while remaining:
        if remaining & 1:
            updated = {}
            for u, cost in distances.items():
                for v, weight in matrix[u].items():
                    candidate = cost + weight
                    previous = updated.get(v)
                    if previous is None or candidate < previous:
                        updated[v] = candidate
            distances = updated

        remaining //= 2
        if remaining:
            squared = []
            for row in matrix:
                result = {}
                for middle, first in row.items():
                    for v, second in matrix[middle].items():
                        candidate = first + second
                        previous = result.get(v)
                        if previous is None or candidate < previous:
                            result[v] = candidate
                squared.append(result)
            matrix = squared

    return distances.get(end)

