def solve(data):
    values = data["values"]
    k = data["k"]
    n = len(values)

    if k <= 0 or k > n:
        return []

    queue = []
    head = 0
    result = []

    for i, value in enumerate(values):
        while len(queue) > head and values[queue[-1]] >= value:
            queue.pop()
        queue.append(i)

        if queue[head] <= i - k:
            head += 1

        if i >= k - 1:
            result.append(values[queue[head]])

    return result

def solve(data):
    stack = []
    quote = None
    escaped = False
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in data:
        if quote is not None:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == quote:
                quote = None
        elif char == '"' or char == "'":
            quote = char
        elif char == '(' or char == '[' or char == '{':
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False

    return quote is None and not escaped and not stack

def solve(data):
    n = data["n"]
    source = data["source"]
    target = data["target"]
    prev = [None] * n
    prev[source] = 0
    best = 0 if source == target else None

    for _ in range(data["k"]):
        curr = [None] * n
        for u, v, weight in data["edges"]:
            cost = prev[u]
            if cost is not None:
                cost += weight
                old = curr[v]
                if old is None or cost < old:
                    curr[v] = cost
        cost = curr[target]
        if cost is not None and (best is None or cost < best):
            best = cost
        if not any(value is not None for value in curr):
            break
        prev = curr

    return best
